export const getIngestEventsUrl = () => {
  return `/api/ingest/events`;
};

export const ingestEvents = async (
  ingestEventsBody: IngestEventsBody,
  options?: RequestInit,
): Promise<IngestEvents200> => {
  return customFetch<IngestEvents200>(getIngestEventsUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(ingestEventsBody),
  });
};

